"""Working script for the spring-quarter shipped-orders reconciliation.

Subcommands:
  fetch-orders     walk every /orders page, cache raw bodies in pages/
  fetch-customers  fetch each needed customer once, cache in customers.json
Everything is resumable: validated responses are cached on disk.
"""
import json
import os
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime

BASE = "http://localhost:8080"
WORK = os.path.dirname(os.path.abspath(__file__))
PAGES = os.path.join(WORK, "pages")
CUSTOMERS = os.path.join(WORK, "customers.json")
LOG = os.path.join(WORK, "events.log")


def log(msg):
    line = f"{datetime.now().strftime('%H:%M:%S')} {msg}"
    with open(LOG, "a") as f:
        f.write(line + "\n")
    print(line, flush=True)


class BadResponse(Exception):
    pass


class Client:
    def __init__(self):
        self.token = None
        self.tokens_issued = 0
        self.requests = 0
        self.rate_limited = 0

    def _raw(self, path, method="GET", auth=True):
        req = urllib.request.Request(BASE + path, method=method)
        if auth and self.token:
            req.add_header("Authorization", "Bearer " + self.token)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read().decode("utf-8")
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read().decode("utf-8", "replace")

    @staticmethod
    def _retry_after(headers, body):
        waits = []
        h = {k.lower(): v for k, v in headers.items()}
        if "retry-after" in h:
            try:
                waits.append(float(h["retry-after"]))
            except ValueError:
                pass
        try:
            j = json.loads(body)
            if isinstance(j, dict) and "retry_after" in j:
                waits.append(float(j["retry_after"]))
        except (ValueError, TypeError):
            pass
        return max(waits) if waits else None

    def refresh_token(self):
        attempt = 0
        while True:
            attempt += 1
            if attempt > 30:
                raise RuntimeError("could not obtain a token after 30 attempts")
            try:
                status, headers, body = self._raw("/token", method="POST", auth=False)
            except (urllib.error.URLError, OSError) as e:
                log(f"token: transport error {e!r}; retrying")
                time.sleep(min(2 ** attempt, 20))
                continue
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                except (ValueError, KeyError, TypeError):
                    log(f"token: unparseable 200 body {body[:200]!r}")
                    time.sleep(1)
                    continue
                self.token = tok
                self.tokens_issued += 1
                log(f"token: issued {tok}")
                return
            if status == 429:
                wait = self._retry_after(headers, body) or 1.0
                log(f"token: 429 (headers={headers.get('Retry-After')!r} body={body[:120]!r}); waiting {wait}s")
                time.sleep(wait + 0.1)
                attempt -= 1
                continue
            log(f"token: HTTP {status} {body[:300]!r}")
            time.sleep(min(2 ** attempt, 20))

    def get_json(self, path, validate=None, allow_404=False, max_attempts=25):
        """GET an authenticated JSON resource, repeating on any failure.

        Returns (status, data). Only returns non-200 for a 404 when allow_404 is set
        and the 404 has been confirmed on several consecutive attempts.
        """
        if self.token is None:
            self.refresh_token()
        failures = 0
        auth_failures = 0
        not_found = 0
        while True:
            if failures >= max_attempts:
                raise RuntimeError(f"{path}: giving up after {failures} failed attempts")
            try:
                status, headers, body = self._raw(path)
            except (urllib.error.URLError, OSError) as e:
                failures += 1
                log(f"{path}: transport error {e!r}; retry {failures}")
                time.sleep(min(2 ** failures, 20))
                continue
            self.requests += 1
            if status == 200:
                try:
                    data = json.loads(body)
                    if validate:
                        validate(data)
                    return 200, data
                except (ValueError, BadResponse) as e:
                    failures += 1
                    log(f"{path}: HTTP 200 but bad body ({e}); body[:300]={body[:300]!r}; retry {failures}")
                    time.sleep(1)
                    continue
            if status == 429:
                self.rate_limited += 1
                wait = self._retry_after(headers, body)
                log(f"{path}: 429 Retry-After={headers.get('Retry-After')!r} body={body[:120]!r}; waiting {wait or 1.0}s")
                time.sleep((wait or 1.0) + 0.1)
                continue
            if status in (401, 403):
                auth_failures += 1
                log(f"{path}: HTTP {status} headers={ {k: v for k, v in headers.items() if k.lower() not in ('server', 'date')} } body={body[:300]!r}; new token")
                if auth_failures > 6:
                    raise RuntimeError(f"{path}: repeated auth failures with fresh tokens")
                self.refresh_token()
                continue
            if status == 404 and allow_404:
                not_found += 1
                log(f"{path}: HTTP 404 body={body[:200]!r} (seen {not_found}x)")
                if not_found >= 3:
                    return 404, body
                time.sleep(1)
                continue
            failures += 1
            log(f"{path}: HTTP {status} body={body[:300]!r}; retry {failures}")
            time.sleep(min(2 ** failures, 20))


def validate_page(requested):
    def check(d):
        if not isinstance(d, dict):
            raise BadResponse("page body is not an object")
        for k in ("page", "total_pages", "items", "next"):
            if k not in d:
                raise BadResponse(f"missing key {k!r}")
        if not isinstance(d["items"], list):
            raise BadResponse("items is not a list")
        if d["page"] != requested:
            raise BadResponse(f"asked for page {requested}, got page {d['page']}")
    return check


def fetch_orders():
    os.makedirs(PAGES, exist_ok=True)
    client = Client()
    page = 1
    seen_total = set()
    while True:
        cache = os.path.join(PAGES, f"page_{page:03d}.json")
        if os.path.exists(cache):
            with open(cache) as f:
                data = json.load(f)
            log(f"page {page}: cached")
        else:
            _, data = client.get_json(f"/orders?page={page}", validate=validate_page(page))
            with open(cache, "w") as f:
                json.dump(data, f)
            log(f"page {page}: fetched items={len(data['items'])} total_pages={data['total_pages']} next={data['next']}")
        seen_total.add(data["total_pages"])
        nxt = data["next"]
        if nxt is None:
            break
        expected = f"/orders?page={page + 1}"
        if nxt != expected:
            log(f"WARNING: page {page} next={nxt!r}, expected {expected!r}; following it anyway")
        page = int(nxt.rsplit("=", 1)[1])
    log(f"done: last page={page}, total_pages values seen={sorted(seen_total)}, "
        f"requests={client.requests}, tokens issued={client.tokens_issued}, 429s={client.rate_limited}")


def fetch_customers(ids):
    client = Client()
    cache = {}
    if os.path.exists(CUSTOMERS):
        with open(CUSTOMERS) as f:
            cache = json.load(f)

    def check(d):
        if not isinstance(d, dict) or "discount_pct" not in d or "region" not in d or "id" not in d:
            raise BadResponse("customer body missing id/region/discount_pct")

    for cid in ids:
        if cid in cache:
            continue
        status, data = client.get_json(f"/customers/{cid}", validate=check, allow_404=True)
        cache[cid] = data if status == 200 else {"_status": status, "_body": data}
        with open(CUSTOMERS, "w") as f:
            json.dump(cache, f, indent=1, sort_keys=True)
        log(f"customer {cid}: {cache[cid]}")
    log(f"customers done: {len(cache)} cached, requests={client.requests}, "
        f"tokens issued={client.tokens_issued}, 429s={client.rate_limited}")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "fetch-orders":
        fetch_orders()
    elif cmd == "fetch-customers":
        with open(sys.argv[2]) as f:
            fetch_customers(json.load(f))
    else:
        sys.exit(__doc__)

